import json

with open('inventory.json') as f:
    inv = json.load(f)

rejected = []
with open('transactions.txt') as f:
    lines = f.read().splitlines()

for lineno, line in enumerate(lines, 1):
    parts = line.split()
    if not parts:
        continue
    if len(parts) != 3:
        rejected.append(lineno)
        continue
    op, sku, qty_text = parts
    try:
        qty = int(qty_text)
    except ValueError:
        rejected.append(lineno)
        continue
    if op == 'add':
        inv[sku] = inv.get(sku, 0) + qty
    elif op == 'remove':
        if sku not in inv or inv[sku] - qty < 0:
            rejected.append(lineno)
        else:
            inv[sku] -= qty
    else:
        rejected.append(lineno)

with open('inventory_after.json', 'w') as f:
    json.dump(inv, f, indent=2)
    f.write('\n')

with open('rejected.txt', 'w') as f:
    for lineno in rejected:
        f.write(f'{lineno}\n')
